<div class="hero"><div><span>مدیریت</span><h1><?=htmlspecialchars($heading)?></h1></div><a class="primary btn" href="<?=$createUrl?>&new=1">افزودن</a></div><?php if(isset($_GET['new'])): ?><form class="card form-grid" method="post"><input type="hidden" name="action" value="<?=$action?>"><?php if($action==='create_customer'): ?><label>نام مشتری<input name="name" required></label><label>یادداشت<input name="notes"></label><?php elseif($action==='create_product'): ?><label>نام غذا<input name="name" required></label><label>قیمت<input name="price" type="number" min="0" required></label><?php else: ?><label>نوع سفارش<select name="order_type"><option>حضوری</option><option>بیرون‌بر</option><option>تلفنی</option><option>ارسال</option></select></label><label>مبلغ<input name="total" type="number" min="0" required></label><?php endif; ?><button class="primary">ثبت</button></form><?php endif; ?><div class="card"><table><?php if($action==='create_customer'): ?><tr><th>نام</th><th>یادداشت</th><th>تاریخ</th></tr><?php foreach($rows as $r): ?><tr><td><?=$r['name']?></td><td><?=$r['notes']?></td><td><?=$r['created_at']?></td></tr><?php endforeach; ?><?php elseif($action==='create_product'): ?><tr><th>غذا</th><th>قیمت</th><th>وضعیت</th></tr><?php foreach($rows as $r): ?><tr><td><?=$r['name']?></td><td><?=number_format($r['price'])?></td><td><?=$r['status']?></td></tr><?php endforeach; ?><?php else: ?><tr><th>شماره</th><th>نوع</th><th>مبلغ</th><th>وضعیت</th><th>زمان</th></tr><?php foreach($rows as $r): ?><tr><td>#<?=$r['order_no']?></td><td><?=$r['order_type']?></td><td><?=number_format($r['total_amount'])?></td><td><?=$r['status']?></td><td><?=$r['created_at']?></td></tr><?php endforeach; ?><?php endif; ?></table></div>